seq = ""
with open("region.fasta") as f:
    for line in f:
        if line.startswith(">"):
            continue
        seq += line.strip()

L = len(seq)
print("Length:", L)
from collections import Counter
c = Counter(seq)
gc = (c['G']+c['C'])/L*100
print("GC pct: %.1f" % gc)
print("A:%d T:%d G:%d C:%d" % (c['A'], c['T'], c['G'], c['C']))

def revcomp(s):
    comp = {'A':'T','T':'A','C':'G','G':'C'}
    return ''.join(comp[b] for b in reversed(s))

def translate(s):
    code = {
    'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L',
    'ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V',
    'TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P',
    'ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
    'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q',
    'AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E',
    'TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
    'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
    out=[]
    for i in range(0,len(s)-2,3):
        out.append(code.get(s[i:i+3],'X'))
    return ''.join(out)

# GC skew in 100bp windows
print("\nGC skew (100bp windows):")
for i in range(0, L, 100):
    w = seq[i:i+100]
    g=w.count('G'); c=w.count('C')
    skew = (g-c)/(g+c) if (g+c)>0 else 0
    print("%4d-%4d  GC=%.2f skew=%+.3f" % (i+1, min(i+100,L), (g+c)/len(w)*100, skew))

# Find all ORFs (start ATG, stop *), min length
stops = ['TAA','TAG','TGA']
print("\nLong ORFs (>=100 codons) across all 6 frames:")
for strand, s in [('+', seq), ('-', revcomp(seq))]:
    for fr in range(3):
        sub = s[fr:]
        # find start codons followed by stop
        for m in __import__('re').finditer('ATG', sub):
            pos = m.start()
            # translate from pos
            prot = translate(sub[pos:])
            if '*' in prot:
                end = prot.index('*')
                aa = end
                if aa >= 100:
                    # coordinate on original seq
                    if strand=='+':
                        cstart = fr+pos+1
                        cend = fr+pos+ end*3 +3
                    else:
                        cstart = L - (fr+pos) 
                        cend = L - (fr+pos+ end*3)
                    print("strand %s frame %d: %d aa, %s:%d-%d" % (strand, fr, aa, strand, cstart, cend))

